"""Post-run semantic assessment; the first response and frozen protocol stay unchanged."""
import json,hashlib
from pathlib import Path
ROOT=Path(__file__).resolve().parent;folder=ROOT/'runs/retention'
read=lambda p:json.loads(p.read_text(encoding='utf-8'))
gold=read(ROOT/'fixtures/retention.gold.json');corpus=read(ROOT/'fixtures/retention.corpus.json')
review=read(folder/'researcher/review.json');trace=read(folder/'trace.json');provenance=read(folder/'provenance.json')
judgements={
 'theme_01':('pass',['c2','c3'],'Preserves the subject’s taxonomy, reason model, provisional thresholds, duplicate-key correction and insufficient-fields boundary. Credits the reviewer who identified title-level false alarms. The final story does not claim sole business-policy authority.'),
 'theme_02':('pass',['c2','c3'],'Keeps initial implementation and fixtures, credits Contributor 09 with finding the cross-currency defect, and credits the subject with the currency guard and tests. Retains the reviewer’s concern about the 45-day reference-free window after approval.'),
 'theme_03':('pass',['c4'],'Preserves the reviewer’s eleven-flag example, the subject’s grouping proposal and implementation, the export owner’s constraint, and the keyboard-focus regression and fix. Explicitly says underlying flags and rules were not suppressed.'),
 'theme_04':('pass',['c6'],'Keeps the subject’s pilot-label analysis, 14-day proposal and revised three-state design after Operations feedback. Credits Contributor 10 with production integration and conflict resolution, while retaining the subject’s design, tests and final review. The uncertain late reversals stay visible.'),
 'theme_05':('pass',['c8'],'Keeps the limited continuation mandate, monitoring/fallback runbook and 35-minute staged training for both shift leads. Explicitly excludes ordinary-reviewer training and wider rollout.'),
 'theme_06':('pass',['c9','c10'],'Preserves the type-change trigger, silent zero-row behavior, roughly two-hour delay, the subject’s validation miss and corrective tests, and Contributor 07’s unannounced export change. Keeps the fallback and successful resumption; does not assign sole blame or imply the whole processing cycle failed.'),
 'theme_07':('pass',['c5','c7'],'The 24 selected statements, medians of 19 and 12 minutes, four reviewers, and 45 useful/12 incorrect/6 unclear flags out of 63 all survive into the account. Retains sample selection and the absence of an independent missed-exception audit. Does not infer a population-wide causal gain or accuracy rate.'),
 'theme_08':('pass',['c10','c11','c12'],'Preserves April completion, May’s 34 queue-led and seven spreadsheet-led reviews out of 41, missing timing entries, and June use by both leads and two of six reviewers. Keeps mixed working practices and the two-imprint boundary instead of calling the tool abandoned or broadly adopted.'),
 'theme_09':('pass',['c13'],'Preserves the scheduled-feed reversal-reference dependency, Finance’s deferral, continued heuristic limits and no wider-rollout owner or date. Does not import the August extension decision. A role label in this claim separately overstates the pilot-export offer as delivered; see the semantic criticism.'),
 'theme_10':('pass',['c10','c14'],'Preserves spreadsheet annotation practice, the July bulk-note backlog and its classification as an inconvenience rather than a processing blocker.'),
 'theme_11':('partial',['c1','c6','c8','c9','c11'],'Separates export ownership, production integration, reviewer feedback and operational authority. However, Contributor 08’s authorship of the evaluation reports disappears from both the saved metric notes and the final roles. The numbers are not falsely credited to the subject, but the full ownership map remains incomplete.')
}
records=read(folder/'result.json')['records'];read_ids={r['id'] for r in records};themes=[]
for t in gold['themes']:
    status,ids,assessment=judgements[t['id']]
    assert all(any(c['id']==id for c in review['claims']) for id in ids)
    themes.append(dict(t,status=status,claim_ids=ids,assessment=assessment,unread_anchors=[id for id in t['anchors'] if id not in read_ids]))
events=trace['events'];plan=trace['planning'];receipt=trace['completion_receipt']
contexts={e['arguments']['id'] for e in events if e['tool']=='read_context' and e['result'].get('end_reached')}
sweeps={(e['arguments']['source'],e['arguments']['window']) for e in events if e['tool']=='list_roots' and e['result'].get('end_reached')}
counts={'fully_met':sum(t['status']=='pass' for t in themes),'partial':sum(t['status']=='partial' for t in themes),'missed':sum(t['status']=='missed' for t in themes),'themes':len(themes),'full_records':len(read_ids),'accessible_records':len(gold['expected_records']),'source_calls':trace['source_calls'],'requests':trace['requests'],'cache_hits':trace['cache_hits'],'remaining_source_calls':receipt['counts']['source_calls_remaining'],'remaining_requests':receipt['counts']['requests_remaining'],'completed_contexts':len(contexts),'unfinished_contexts':len(plan['unopened_contexts']),'completed_source_window_sweeps':len(sweeps),'unread_surfaced_records':len(plan['unread_surfaced_records']),'unchecked_attachments':len(plan['unchecked_attachments']),'exact_spans':provenance['quote_count'],'submitted_spans':sum(len(c['evidence']) for c in review['claims']),'completion_receipt_valid':provenance['completion_receipt_valid'],'validation_flags':len(provenance['errors']),'disposition_records':provenance['disposition_records'],'attribution_chains':provenance['attribution_chains'],'writing_packet_calls':sum(e['tool']=='writing_packet' for e in events),'save_notes_calls':sum(e['tool']=='save_notes' for e in events),'saved_notes':len(review['evidence_notes']),'material_notes':provenance['material_notes'],'material_notes_represented':provenance['material_notes_represented'],'narrative_claims':len(review['claims']),'rejection_only_records':len(provenance['rejection_only_records'])}
assessment={
 'headline':'The findings survived writing. Attribution still needs care.',
 'summary':'All 41 accessible records were read and noted. The account retains the measured use, corrections, shared responsibility and stalled dependency. It still loses one evaluator’s credit and turns an offer to supply data into a delivered contribution.',
 'scope_limit':'One untouched synthetic publishing-operations story; one uncoached attempt. Ten of eleven themes fully met, one partial. All 80 selected quotations match. A redundant omission entry fails the output contract, so this is not an end-to-end pass.',
 'expected_records':len(gold['expected_records']),'themes':themes,
 'issue_heading':'Complete record links do not guarantee complete meaning.',
 'issues':[
  {'severity':'One contributor disappears before writing','claim_ids':['c5','c7','c11'],'detail':'Contributor 08 wrote the timing, flag-label and May evaluation reports. Their numbers survive, but that credit is absent from the saved notes and final roles. Compiling every claim protects what was selected; it cannot recover attribution already dropped during note-taking.'},
  {'severity':'An offer becomes a delivered contribution','claim_ids':['c13'],'detail':'The role table says Contributor 07 provided one-off pilot reference data. chat:003 says they can add it. The record supports an offer and a production constraint, not proof of delivery. The main claim keeps the unresolved feed dependency accurately, but the role’s stronger wording is unsupported.'},
  {'severity':'A cited record is also called omitted','claim_ids':['c10'],'detail':'docs:010 supplies the limited-continuation quotation in c10 and is also placed in omitted_material. The explanation says its other content is covered elsewhere, which is understandable, but that field is for wholly uncited material records. The validator retains this contract failure. The record itself is not missing.'},
  {'severity':'The old bookkeeping repair has limited live evidence','claim_ids':[],'detail':'Regression tests now reconcile a record used only to reject a conclusion while still rejecting invented sources. In this new story, every rejected-conclusion source is also cited by a positive claim. The specific rejection-only path therefore passes unit tests but was not exercised by this AI run.'},
  {'severity':'Recovery works, but notes arrived late','claim_ids':[],'detail':'The model spent all 45 source calls before making nine writing-packet recoveries and nine note submissions. It recovered evidence after exhaustion and made no false missing-citation claim, but did not build interpretive notes incrementally as requested. The underlying source journal remained persistent throughout.'},
  {'severity':'The audit attachment remains unchecked','claim_ids':['c5','c7'],'detail':'The parent document says its reviewer-by-reviewer export cannot be opened. The model reports that parent statement and its own lack of an attachment read separately. Aggregate results remain source reports rather than independently recomputed measurements.'}
 ],
 'limitations':[
  'The separate AI author received only a generic fictional brief, schema and domain-diversity exclusions. The 42-record story exceeds the requested 32–40 but falls inside the preregistered 32–64 acceptance range. It was accepted unchanged. No previous story, private record, implementation or researcher prompt was supplied.',
  'Author and researcher were separate isolated sessions using the same provider/default model family. The exact model version was not captured. Procedural independence is not equivalent to a human-authored benchmark or an independent-provider replication.',
  'This assistant manually compared the hidden author rubric and original sources only after the first response. Ten full themes and one partial measure this story’s thematic coverage, not general reliability. The unsupported offer-to-delivery role was found beyond the rubric and remains separately flagged.',
  'All 41 accessible primary records, including three distractors, were returned in full. One August record lies beyond the July horizon and was not supplied. All discovered contexts, including chains three levels below the root, and all nine source/window sweeps completed.',
  'All 41 full reads have persistent judgments: 38 material and three irrelevant. Every material record is referenced by a claim or rejection. That is record-level coverage only; the missing evaluator credit demonstrates that not every semantic detail survived.',
  'Nine cache-only writing packets recovered all 41 records after the source-call limit. Nine save_notes calls persisted judgments, followed by research_status and finish_check: 65 requests in total, leaving 15 slots. There were no ordinary cached read_record replays; writing recovery is counted separately.',
  'All 80 selected quotations resolve to exact original spans. The account joins fourteen first-response claim statements and their limits in the model’s chosen order. It is deliberately compiled rather than independently summarised; this changes the writing interface and does not demonstrate better unconstrained summarisation.',
  'The final receipt is valid at the 45-source-call limit, with no unread primary records or missing notes. One attachment remains unchecked. A valid receipt certifies observed budget and discovery state, not claim truth or source completeness.',
  'The sole structural failure is the contradictory docs:010 omission entry. It was not removed or converted into a pass. The role overstatement and evaluator-credit omission are semantic issues that the span validator cannot detect.',
  'The specific rejection-only bookkeeping path is covered by independent unit fixtures, including invalid-source cases, but no rejection-only record occurred in this live story. Attachment classification is likewise based on the parent record and fixture audit, not a successful attachment request.',
  'Twenty local writing/audit calls were added to 45 source calls. The CLI reported 1,451,089 input tokens, including 1,370,496 cached tokens, and 8,720 output tokens. These are provider usage counters, not a price calculation or evidence that the workflow is cheaper; no controlled efficiency comparison was run.',
  'No source fixture, frozen prompt, schema, server or compiler was changed after story generation. There was one substantive research attempt, with no coaching or retry. Different story content and the compiled narrative mechanism prevent causal comparison with earlier scores. Private archives and live integrations were not accessed.'
 ],
 'method':'The protocol, cache recovery, note journal, compiler, schemas and tests were hash-frozen before separate AI story generation. A fresh researcher chose all reads and then recovered cached evidence for writing. After its first response, this assistant checked the hidden rubric, original sources, saved notes, source spans and completion receipt. The compiler only resolves quotations, derives links and assembles the chosen claim sentences; evaluator findings are never fed back to the model.',
 'next_experiment':'Test explicit attribution and action-state checks in saved notes: who wrote an evaluation, who offered something, and what proves delivery. Clarify whole-record exclusions versus partial-content notes, and check a complete draft before sealing it. Use another untouched story; preserve this result.',
 'summary_counts':counts,'final_planning':plan,'completion_receipt':{k:v for k,v in receipt.items() if k!='planning'},'validation_errors':provenance['errors'],
 'adjudicator':'This assistant; manual rubric assessment plus source-level semantic checks','substantive_attempts':1,'content_edited':False,'prompt_frozen':True,'private_records_supplied':False,
 'raw_response_sha256':hashlib.sha256((folder/'researcher/response.json').read_bytes()).hexdigest(),'compiled_review_sha256':hashlib.sha256((folder/'researcher/review.json').read_bytes()).hexdigest(),'gold_sha256':hashlib.sha256((ROOT/'fixtures/retention.gold.json').read_bytes()).hexdigest()
}
assert (counts['fully_met'],counts['partial'],counts['missed'])==(10,1,0)
assert counts['exact_spans']==counts['submitted_spans']==80 and counts['completion_receipt_valid']
assert counts['validation_flags']==1 and counts['saved_notes']==counts['full_records']==41
assert counts['material_notes']==counts['material_notes_represented']==38
(folder/'assessment.json').write_text(json.dumps(assessment,indent=2,ensure_ascii=False),encoding='utf-8')
(folder/'attachments.json').write_text(json.dumps([a|{'read_by_researcher':False,'observed_result':'Evaluator copy; researcher did not request attachment. Parent document reports it unavailable.'} for a in corpus['attachments']],indent=2),encoding='utf-8')
print(json.dumps(counts))
